/// App logo — gold→purple gradient hexagon, rendered without a color override.
pub const LOGO: &str = r##"<svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><defs><linearGradient id="firmium-logo-grad" x1="0%" y1="0%" x2="100%" y2="100%"><stop offset="0%" stop-color="#e8c97e"/><stop offset="100%" stop-color="#863bff"/></linearGradient></defs><polygon points="12,2 22,7 22,17 12,22 2,17 2,7" stroke="url(#firmium-logo-grad)" stroke-width="2" stroke-linejoin="round"/></svg>"##;

/// Build a square icon recolored to `color`.
pub fn icon<'a, Message: 'a>(src: &'static str, size: f32, color: Color) -> Element<'a, Message> {
    iced::widget::svg(Handle::from_memory(src.as_bytes()))
        .width(Length::Fixed(size))
        .height(Length::Fixed(size))
        .style(move |_theme, _status| svg::Style { color: Some(color) })
        .into()
}

/// The logo, keeping its embedded gradient (no recolor).
pub fn logo<'a, Message: 'a>(size: f32) -> Element<'a, Message> {
    iced::widget::svg(Handle::from_memory(LOGO.as_bytes()))
        .width(Length::Fixed(size))
        .height(Length::Fixed(size))
        .into()
}
